import torch,json
E=W('model.embed_tokens.weight'); g=W('model.embedding_norm.weight'); U=E*g
def ids(ws): return sorted(set(encode(w)[0] for w in ws))
cats={'code':[' def',' return',' import',' self',' print',' class',' elif',' lambda',' None',' True','():',' __','==',' range',' len',' append','();',' const',' var',' function',' int',' void',' public',' static',' std'],
'french':[' le',' la',' les',' des',' est',' une',' du',' pour',' avec',' sont',' dans',' nous',' vous',' mais',' été',' très',' aussi',' leur',' cette',' être'],
'digits':[' 1',' 2',' 3',' 4',' 5',' 6',' 7',' 8',' 9',' 0'],
'country':[' France',' Germany',' Italy',' Spain',' Japan',' China',' India',' Brazil',' Canada',' Russia',' Egypt',' Paris',' Berlin',' Rome',' Tokyo',' London'],
'weekday':[' Monday',' Tuesday',' Wednesday',' Thursday',' Friday',' Saturday',' Sunday'],
'month':[' January',' February',' March',' April',' May',' June',' July',' August',' September',' October',' November',' December']}
mu=U.mean(0)
D={k:(U[ids(v)]-mu).mean(0) for k,v in cats.items()}
D={k:v/v.norm() for k,v in D.items()}
for L in [0,1]:
    w2=W(f'model.layers.{L}.feed_forward.w2.weight')  # 2048x11776
    cn=w2/w2.norm(dim=0,keepdim=True)
    C={k:(D[k]@cn) for k in D}
    for k in D:
        other=torch.stack([C[j].abs() for j in D if j!=k]).max(0).values
        s=C[k].abs()-0.5*other
        top=s.argsort(descending=True)[:128].tolist()
        json.dump({'kind':'mlp_cluster','layer':L,'indices':top},open(f'/work/mlp{L}{k}.json','w'))
        print(L,k,'top cos',round(C[k].abs()[top[:5]].mean().item(),3), round(C[k].abs()[top].mean().item(),3))
